'use strict'

const svgo = require('svgo/lib/svgo-node.js')

const legacyPluginNames = {
  cleanupIDs: 'cleanupIds'
}

const normalizePluginOverrides = (overrides = {}) => {
  const normalized = {}

  for (const name of Object.keys(overrides)) {
    normalized[legacyPluginNames[name] || name] = overrides[name]
  }

  return normalized
}

const normalizePlugin = (plugin) => {
  if (!plugin || typeof plugin !== 'object') return plugin

  if (plugin.name !== 'preset-default' || !plugin.params || !plugin.params.overrides) {
    return plugin
  }

  return {
    ...plugin,
    params: {
      ...plugin.params,
      overrides: normalizePluginOverrides(plugin.params.overrides)
    }
  }
}

const normalizeConfig = (config = {}) => {
  if (!Array.isArray(config.plugins)) return config

  return {
    ...config,
    plugins: config.plugins.map(normalizePlugin)
  }
}

const optimize = (input, config) => {
  try {
    return svgo.optimize(input, normalizeConfig(config))
  } catch (err) {
    if (err && err.name === 'SvgoParserError') {
      return {
        error: err.toString(),
        modernError: err
      }
    }

    throw err
  }
}

module.exports = {
  ...svgo,
  optimize
}

