    37	  if (!Array.isArray(config.plugins)) return config
    38	
    39	  return {
    40	    ...config,
    41	    plugins: config.plugins.map(normalizePlugin)
    42	  }
    43	}
    44	
    45	const optimize = (input, config) => {
    46	  try {
    47	    return svgo.optimize(input, normalizeConfig(config))
    48	  } catch (err) {
    49	    if (err && err.name === 'SvgoParserError') {
    50	      return {
    51	        error: err.toString(),
    52	        modernError: err
    53	      }
    54	    }
    55	
    56	    throw err
    57	  }
    58	}
    59	
    60	module.exports = {
    61	  ...svgo,
    62	  optimize
    63	}
